"""SVE2 sign primitive candidate emitter (docs/37, remaining fields).

x265 calSign_neon: dst[i] = sign(src1[i] - src2[i]) for i in [0, endX).
The SVE candidate uses two predicate compares + sel/add, so one 32-byte
vector pass replaces the NEON 8-byte loop and scalar tail.
"""


def emit(func_name="dynopt_sign_sve2"):
    return """\
// Generated by tools/emit_sign_sve2_shared.py -- do not edit by hand.
#include <arm_sve.h>
#include <stdint.h>

extern "C" void %s(int8_t* dst, const uint8_t* src1,
                   const uint8_t* src2, int endX)
{
    const svint8_t one = svdup_n_s8(1);
    const svint8_t neg = svdup_n_s8(-1);
    const svint8_t zero = svdup_n_s8(0);
    for (int off = 0; off < endX; off += 32)
    {
        const int n = endX - off < 32 ? endX - off : 32;
        const svbool_t pg = svwhilelt_b8((uint32_t)0, (uint32_t)n);
        const svuint8_t a = svld1_u8(pg, src1 + off);
        const svuint8_t b = svld1_u8(pg, src2 + off);
        const svbool_t gt = svcmpgt_u8(pg, a, b);
        const svbool_t lt = svcmpgt_u8(pg, b, a);
        svint8_t g = svsel_s8(gt, one, zero);
        svint8_t l = svsel_s8(lt, neg, zero);
        svst1_s8(pg, dst + off, svadd_s8_x(pg, g, l));
    }
}
""" % func_name


def emit_combo(combo):
    return emit()
